#!/usr/bin/env bash
# Print the three most frequent client IPs in access.log.  For equal counts,
# retain log order by sorting on the first line on which each IP occurred.
set -euo pipefail

awk '
    {
        ip = $1
        if (!(ip in count))
            first[ip] = ++sequence
        ++count[ip]
    }
    END {
        for (ip in count)
            printf "%d\t%d\t%s\n", count[ip], first[ip], ip
    }
' access.log |
    LC_ALL=C sort -t $'\t' -k1,1nr -k2,2n |
    head -n 3 |
    cut -f3

#!/usr/bin/env bash
# Print the three most frequent client IPs in access.log. For equal counts,
# preserve the order in which the IPs first appeared in the log.
set -euo pipefail
cd "$(dirname "$0")"

awk '
    {
        ip = $1
        if (!(ip in count))
            first[ip] = ++sequence
        ++count[ip]
    }
    END {
        for (ip in count)
            printf "%d\t%d\t%s\n", count[ip], first[ip], ip
    }
' access.log |
    LC_ALL=C sort -t $'\t' -k1,1nr -k2,2n |
    sed -n '1,3p' |
    cut -f3
